    const attemptBody=attempts.length?`<div class='table-wrap'><table class='data-table' data-testid='paper-execution-attempts'><thead><tr><th>${ui('请求时间','Requested')}</th><th>Token</th><th>${ui('方向','Side')}</th><th>${ui('状态','Status')}</th><th>${ui('报价时间','Quote time')}</th><th>${ui('原因','Reason')}</th></tr></thead><tbody>${attempts.map(item=>`<tr><td class='mono nowrap'>${esc(dateTime(item.requested_at))}</td><td class='mono'>${esc(shortAddress(item.token_id))}</td><td>${esc(item.side||'—')}</td><td>${statusPill(item.status,stateLabel(item.status))}</td><td class='mono'>${esc(dateTime(item.quote_observed_at))}</td><td class='muted'>${esc(item.reason||'—')}</td></tr>`).join('')}</tbody></table></div>`:empty(ui('尚无模拟执行尝试','No simulated execution attempts'),ui('只有 CANDIDATE 进入执行阶段或持仓触发退出时才会记录。','Attempts are recorded only when a CANDIDATE reaches execution or a position triggers an exit.'),'⌁');
